WITH lines AS (SELECT t.id, t.customer_id, t.created_at, t.coupon_codes, pos + 1 AS item_no, rec.qty, rec.price, rec.promo FROM carts t LATERAL VIEW POSEXPLODE(t.items) x AS pos, rec) SELECT DATE_TRUNC('HOUR', created_at) AS hour_window, item_no, SORT_ARRAY(COLLECT_SET(promo)) AS promo_list, SUM(CASE WHEN promo = 'BUNDLE' THEN qty ELSE 0 END) AS bundle_qty, ROUND(AVG(item_no), 2) AS avg_item_no, GROUPING(DATE_TRUNC('HOUR', created_at)) AS grouping_id FROM lines GROUP BY GROUPING SETS ((DATE_TRUNC('HOUR', created_at), item_no), (DATE_TRUNC('HOUR', created_at)), ()) ORDER BY item_no DESC NULLS FIRST;
